/**
 * 合并入库通知
 * 输入：刷出节点给出的 { items: [...], claimedFiles: [...] }（同一剧同一季的一批入库）
 * 单集：原样发送；多集（含多集单文件如 E01-E02）：合并成 “剧名 (年份) S05 E01-E08 已入库”。
 * 所有输出构建完成后再清理 .processing 队列文件，避免中途报错丢通知。
 */

// ======================= 可配置图标 =======================
// MoviePilot 默认图标（队列条目缺失图标时的统一兜底）
const MP_DEFAULT_ICON = ""; // 可选：MoviePilot 默认兜底图标 URL（留空则使用 Bark 默认图标）
// =========================================================

const str = (v) => (v === null || v === undefined ? "" : String(v));
const num = (v) => {
    const n = Number(v);
    return Number.isFinite(n) ? n : 0;
};
const round = (v, digits = 2) => {
    const n = Number(v);
    if (!Number.isFinite(n)) return str(n);
    const factor = Math.pow(10, digits);
    return Math.round(n * factor) / factor;
};
const formatSize = (value) => {
    const n = num(value);
    if (n / 1000000000000 >= 1) return `${round(n / 1000000000000, 2)} TB`;
    if (n / 1000000000 >= 1) return `${round(n / 1000000000, 2)} GB`;
    return `${round(n / 1000000, 2)} MB`;
};
let testMode = false;
const utf8Bytes = (ch) => {
    const cp = ch.codePointAt(0);
    if (cp <= 0x7f) return 1;
    if (cp <= 0x7ff) return 2;
    if (cp <= 0xffff) return 3;
    return 4;
};
const clipUtf8 = (text, maxBytes, suffix = "") => {
    const s = str(text);
    let total = 0;
    for (const ch of s) total += utf8Bytes(ch);
    if (total <= maxBytes) return s;
    let suffixBytes = 0;
    for (const ch of suffix) suffixBytes += utf8Bytes(ch);
    const limit = Math.max(0, maxBytes - suffixBytes);
    let used = 0;
    let out = "";
    for (const ch of s) {
        const b = utf8Bytes(ch);
        if (used + b > limit) break;
        out += ch;
        used += b;
    }
    return out.trimEnd() + suffix;
};
const bark = (group, title, body, extra = {}) => {
    const fullTitle = clipUtf8(testMode ? `【🧪测试】 ${title}` : title, 240, "…");
    const safeBody = clipUtf8(body, 2800, "\n…（内容过长已截断）");
    const payload = { group, title: fullTitle, body: safeBody, action: "none" };
    for (const [key, value] of Object.entries(extra)) {
        if (value !== undefined && value !== null && value !== "") payload[key] = value;
    }
    if (!payload.icon) payload.icon = MP_DEFAULT_ICON;
    return payload;
};

const DASH = "—";
const val = (value) => {
    const s = str(value).trim();
    return s || DASH;
};
const score = (value) => {
    const raw = str(value).trim();
    if (!raw) return DASH;
    const n = Number(raw);
    return Number.isFinite(n) ? n.toFixed(1) : raw;
};
const linkJellyfin = (url) => `🎞️在Jellyfin中查看🎞️ ${val(url)}`;
const linkTMDB = (url) => `🔗在TMDB中查看🔗 ${val(url)}`;
const linkHomepage = (url) => `🌐查看影视官网🌐 ${val(url)}`;

const pad = (n) => String(n).padStart(2, "0");
// 连续集数压缩：1..8 -> E01-E08；不连续则用顿号分隔
const formatEpisodes = (episodes) => {
    const sorted = [...new Set(episodes)].sort((a, b) => a - b);
    const parts = [];
    for (let i = 0; i < sorted.length; ) {
        let j = i;
        while (j + 1 < sorted.length && sorted[j + 1] === sorted[j] + 1) j++;
        parts.push(j > i ? `E${pad(sorted[i])}-E${pad(sorted[j])}` : `E${pad(sorted[i])}`);
        i = j + 1;
    }
    return parts.join("、");
};
const extractEpisodes = (item) => {
    const list =
        (Array.isArray(item.episodes) && item.episodes.length && item.episodes) ||
        (Array.isArray(item.meta && item.meta.episodes) && item.meta.episodes.length && item.meta.episodes) ||
        (item.episode !== undefined && item.episode !== null ? [item.episode] : []);
    return list.map(num).filter((n) => n > 0);
};

const out = [];
const filesToCleanup = [];
for (const input of $input.all()) {
    const batchItems = Array.isArray(input.json.items) ? input.json.items.slice() : [];
    const claimedFiles = Array.isArray(input.json.claimedFiles) ? input.json.claimedFiles : [];
    if (!batchItems.length) {
        filesToCleanup.push(...claimedFiles);
        continue;
    }

    if (batchItems.length === 1) {
        const singleBark = { ...batchItems[0].bark };
        if (!singleBark.icon) singleBark.icon = MP_DEFAULT_ICON;
        if (singleBark.attach && !singleBark.image) singleBark.image = singleBark.attach;
        delete singleBark.attach;
        singleBark.title = clipUtf8(singleBark.title, 240, "…");
        singleBark.body = clipUtf8(singleBark.body, 2800, "\n…（内容过长已截断）");
        out.push({ json: { bark: singleBark, source: "MoviePilot", event: "transfer.complete" } });
        filesToCleanup.push(...claimedFiles);
        continue;
    }

    batchItems.sort((a, b) => {
        const ea = extractEpisodes(a)[0] || num(a.episode);
        const eb = extractEpisodes(b)[0] || num(b.episode);
        return ea - eb;
    });
    const meta = batchItems[0].meta || {};
    testMode = Boolean(batchItems[0].bark && String(batchItems[0].bark.title).startsWith("【🧪测试】"));

    const allEpisodes = [];
    for (const item of batchItems) allEpisodes.push(...extractEpisodes(item));
    const uniqueEpisodes = [...new Set(allEpisodes)].sort((a, b) => a - b);
    const episodeText = formatEpisodes(uniqueEpisodes);
    const totalSize = batchItems.reduce((sum, item) => sum + num(item.size), 0);
    const totalFiles = batchItems.reduce((sum, item) => sum + num((item.meta || {}).fileCount), 0);
    const title = `🎬 ${str(meta.show)} S${pad(meta.season)} ${episodeText} 已入库`;
    const body =
        `【集数】${episodeText}（共 ${uniqueEpisodes.length} 集）\n` +
        `【评分】${score(meta.score)}\n` +
        `【流行度】${val(meta.popularity)}\n` +
        `【类别】${val(meta.category)}\n` +
        `【时长】${val(meta.duration)}\n` +
        `【质量】${val(meta.quality)}\n` +
        `【编码格式】${val(meta.encode)}\n` +
        `【合计】${totalFiles} 个文件\n` +
        `【大小】${formatSize(totalSize)}\n\n` +
        `${linkJellyfin(meta.jellyfinUrl)}\n` +
        `${linkTMDB(meta.detailLink)}\n` +
        `${linkHomepage(meta.homepage)}`;

    out.push({
        json: {
            bark: bark("MoviePilot", title, body, { icon: meta.icon, image: meta.image || meta.attach }),
            source: "MoviePilot",
            event: "transfer.complete",
            aggregated: uniqueEpisodes.length || batchItems.length
        }
    });
    filesToCleanup.push(...claimedFiles);
}

// 输出全部构建成功后，再清理抢占到的 .processing 文件
if (filesToCleanup.length) {
    try {
        const fs = require("fs");
        for (const file of filesToCleanup) {
            try {
                fs.unlinkSync(file);
            } catch (e) {
                // 忽略
            }
        }
    } catch (e) {
        // 无 fs 权限时跳过
    }
}

return out;
